crc.pseudo_c:
uint32_t stm32_crc(const uint8_t *data, size_t len) {
    uint32_t crc = 0xFFFFFFFFu;
    size_t nwords = (len + 3) / 4;            // padding ke kelipatan 4
    for (size_t i = 0; i < nwords; i++) {
        uint32_t w; memcpy(&w, data + i*4, 4); // little-endian
        crc ^= w;
        for (int b = 0; b < 32; b++) {
            crc = (crc & 0x80000000u) ? ((crc << 1) ^ 0x04C11DB7u) : (crc << 1);
        }
    }
    return crc;
}
